    if (!full_validation) return Status::OK();

    auto CheckPrefix = [&](size_t i,
                           std::array<uint8_t, BinaryViewType::kPrefixSize> prefix,
                           const uint8_t* data) {
      if (std::memcmp(data, prefix.data(), BinaryViewType::kPrefixSize) == 0) {
        return Status::OK();
