/// Recursively validate that an Arrow array's declared length is consistent with
/// its buffers, offsets, validity bitmap, and children before ClickHouse reads
/// (and reserves memory for) any of it. This protects the per-type readers from
/// out-of-bounds reads on maliciously crafted or corrupted Arrow/Parquet/ORC data.
///
/// The cheap arrow::Array::Validate() (invoked by the caller for the whole tree)
/// already covers buffer/bitmap sizes vs. the declared length (with overflow
/// checks), negative/too-large lengths, null-count sanity, struct/map/fixed-size
/// list child lengths, and the first/last offset of binary-like and list-like
/// arrays. Crucially, it validates buffer sizes BEFORE scanning the validity
/// bitmap, so a truncated bitmap (even with the -1 "unknown null count" sentinel)
/// is rejected without an out-of-bounds scan.
///
/// This routine adds the checks that Validate() only performs under the expensive
/// ValidateFull(): monotonicity/bounds of the full offsets array, and view-struct
/// consistency. We deliberately do NOT run ValidateFull() on string columns,
/// because it would additionally enforce UTF-8 validity, and ClickHouse reads
/// Arrow STRING and BINARY columns as raw bytes (String columns are round-tripped
/// as Arrow STRING by default and may legitimately contain non-UTF-8 data).
void validateArrowArrayData(
    const std::shared_ptr<arrow::ArrayData> & data, const std::string & format_name, const std::string & column_name)
{
    if (!data || !data->type)
        return;

    switch (data->type->id())
    {
        case arrow::Type::BINARY:
        case arrow::Type::STRING:
        {
            const int64_t limit = (data->buffers.size() > 2 && data->buffers[2]) ? data->buffers[2]->size() : 0;
            validateArrowOffsets<int32_t>(*data, limit, format_name, column_name);
            break;
        }
        case arrow::Type::LARGE_BINARY:
        case arrow::Type::LARGE_STRING:
        {
            const int64_t limit = (data->buffers.size() > 2 && data->buffers[2]) ? data->buffers[2]->size() : 0;
            validateArrowOffsets<int64_t>(*data, limit, format_name, column_name);
            break;
        }
        case arrow::Type::LIST:
        case arrow::Type::MAP:
        {
            const int64_t limit = !data->child_data.empty() ? (data->child_data[0]->offset + data->child_data[0]->length) : 0;
            validateArrowOffsets<int32_t>(*data, limit, format_name, column_name);
            break;
        }
        case arrow::Type::LARGE_LIST:
        {
            const int64_t limit = !data->child_data.empty() ? (data->child_data[0]->offset + data->child_data[0]->length) : 0;
            validateArrowOffsets<int64_t>(*data, limit, format_name, column_name);
            break;
        }
        case arrow::Type::STRING_VIEW:
        case arrow::Type::BINARY_VIEW:
        {
            /// View structs need per-element validation (buffer index, offset + size vs.
            /// the referenced variadic buffer, negative sizes). ClickHouse never writes
            /// view types, so reusing Arrow's full validation (including its UTF-8 check
            /// for STRING_VIEW) here is safe.
            auto array = arrow::MakeArray(data);
            auto status = array->ValidateFull();
            if (!status.ok())
                throwMalformedArrowColumn(format_name, column_name, status.ToString());
            break;
        }
        default:
            break;
    }

    for (const auto & child : data->child_data)
        validateArrowArrayData(child, format_name, column_name);

    if (data->dictionary)
        validateArrowArrayData(data->dictionary, format_name, column_name);
}

