/// Full validation of the offsets buffer of a binary-like or list-like array:
/// the offsets must be non-negative, monotonically non-decreasing, and stay
/// within `offset_limit` (the size of the values buffer for binary-like arrays,
/// or the length of the child array for list-like arrays).
///
/// Arrow's cheap Array::Validate() already guarantees that the offsets buffer is
/// large enough to hold length + 1 entries and that the first/last offsets are in
/// range, but it does NOT check that the intermediate offsets are monotonic. A
/// corrupted intermediate offset can make an individual value_length(i) huge (or
/// negative, which wraps to huge when cast to an unsigned size) and drive an
/// out-of-bounds read in the per-row readers below. We check the full offsets
/// array here so that such files are rejected up-front with INCORRECT_DATA.
template <typename OffsetType>
void validateArrowOffsets(
    const arrow::ArrayData & data, int64_t offset_limit, const std::string & format_name, const std::string & column_name)
{
    if (data.length <= 0 || data.buffers.size() < 2 || !data.buffers[1])
        return;

    const auto * offsets = data.GetValues<OffsetType>(1);
    if (offsets == nullptr)
        return;

    int64_t previous_offset = static_cast<int64_t>(offsets[0]);
    if (previous_offset < 0)
        throwMalformedArrowColumn(format_name, column_name, "array starts at a negative offset");

    for (int64_t i = 1; i <= data.length; ++i)
    {
        const int64_t current_offset = static_cast<int64_t>(offsets[i]);
        if (current_offset < previous_offset)
            throwMalformedArrowColumn(
                format_name,
                column_name,
                fmt::format("non-monotonic offset at slot {}: {} < {}", i, current_offset, previous_offset));
        if (current_offset > offset_limit)
            throwMalformedArrowColumn(
                format_name,
                column_name,
                fmt::format("offset at slot {} is out of bounds: {} > {}", i, current_offset, offset_limit));
        previous_offset = current_offset;
    }
}

